import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        // All non-empty decimal prefixes of the first array, obtained by dropping last digits.
        HashSet<Integer> prefixes = new HashSet<>(n * 20);
        for (int i = 0; i < n; i++)
            for (int v = nextInt(); v > 0; v /= 10) prefixes.add(v);
        int answer = 0;
        for (int i = 0; i < m; i++)
            for (int v = nextInt(); v > 0; v /= 10)
                if (prefixes.contains(v)) {
                    answer = Math.max(answer, Integer.toString(v).length());
                    break;
                }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := nextInt(), nextInt()
	// All non-empty decimal prefixes of the first array, obtained by dropping last digits.
	prefixes := make(map[int]struct{}, n*10)
	for i := 0; i < n; i++ {
		for v := nextInt(); v > 0; v /= 10 {
			prefixes[v] = struct{}{}
		}
	}
	answer := 0
	for i := 0; i < m; i++ {
		for v := nextInt(); v > 0; v /= 10 {
			if _, ok := prefixes[v]; ok {
				answer = max(answer, len(strconv.Itoa(v)))
				break
			}
		}
	}
	fmt.Println(answer)
}
